+const navToggle = document.querySelector(".nav-toggle");
+const navMenu = document.querySelector("#primary-menu");
+const cartCount = document.querySelector(".cart-count");
+const filterButtons = document.querySelectorAll(".filter-button");
+const productCards = document.querySelectorAll(".product-card");
+const addCartButtons = document.querySelectorAll(".add-cart");
+const newsletterForm = document.querySelector("#newsletter-form");
+const formMessage = document.querySelector("#form-message");
+const dealHours = document.querySelector("#deal-hours");
+
+let cartItems = 0;
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+
+  navToggle.setAttribute("aria-expanded", String(!isOpen));
+  navMenu.classList.toggle("open", !isOpen);
+  document.body.classList.toggle("menu-open", !isOpen);
+});
+
+navMenu.addEventListener("click", (event) => {
+  if (event.target.matches("a")) {
+    navToggle.setAttribute("aria-expanded", "false");
+    navMenu.classList.remove("open");
+    document.body.classList.remove("menu-open");
+  }
+});
+
+filterButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    const selectedCategory = button.dataset.filter;
+
+    filterButtons.forEach((item) => {
+      item.classList.toggle("active", item === button);
+    });
+
+    productCards.forEach((card) => {
+      const shouldShow =
+        selectedCategory === "all" || card.dataset.category === selectedCategory;
+
+      card.classList.toggle("hidden", !shouldShow);
+    });
+  });
+});
+
+addCartButtons.forEach((button) => {
+  button.addEventListener("click", () => {
+    cartItems += 1;
+    cartCount.textContent = String(cartItems);
+    button.classList.add("added");
+    button.textContent = "Added";
+
+    window.setTimeout(() => {
+      button.classList.remove("added");
+      button.textContent = "Add to cart";
+    }, 1400);
+  });
+});
+
+newsletterForm.addEventListener("submit", (event) => {
+  event.preventDefault();
+  const formData = new FormData(newsletterForm);
+  const email = String(formData.get("email")).trim();
+
+  formMessage.textContent = `Thanks. Product edits will be sent to ${email}.`;
+  newsletterForm.reset();
+});
+
+const updateDealHours = () => {
+  const now = new Date();
+  const endOfDay = new Date(now);
+  endOfDay.setHours(23, 59, 59, 999);
+  const hoursLeft = Math.max(1, Math.ceil((endOfDay - now) / 3600000));
+
+  dealHours.textContent = String(hoursLeft).padStart(2, "0");
+};
+
+updateDealHours();
